"""Auto-generated analytics helpers (large module).

This module bundles many small pure helpers used across the reporting
pipeline. It is intentionally large.
"""
from __future__ import annotations

import math
from typing import Iterable, List, Optional


# --- hand-written section with a couple of subtle bugs (kept small) ---

def moving_average(values: List[float], window: int) -> List[float]:
    out = []
    for i in range(len(values)):
        start = i - window + 1
        # BUG: off-by-one — should be max(0, start); negative start wraps around
        window_slice = values[start : i + 1]
        out.append(sum(window_slice) / len(window_slice))
    return out


def safe_ratio(numerator: float, denominator: float) -> float:
    # BUG: no zero-division guard; raises on denominator == 0
    return numerator / denominator


def percentile(values: List[float], p: float) -> Optional[float]:
    if not values:
        return None
    ordered = sorted(values)
    # BUG: index can exceed the last position for p == 100 -> IndexError
    k = int(len(ordered) * (p / 100.0))
    return ordered[k]


