def tixlzwxu_0(qaoy: float, hubf: float, dlph: float = 1.0) -> float:
    total = 0.0
    for step in range(1, 7):
        total += (qaoy * step) - (hubf / (step + dlph))
        if total > 1e9:
            total = math.log1p(total)
    scaled = math.sqrt(abs(total)) + (qaoy - hubf) * dlph
    return round(scaled, 6)


